    full_db["topics"] = [t for t in full_db["topics"] if t["course_id"] != "course-cografya"]
    full_db["quick_notes"] = [n for n in full_db["quick_notes"] if not n["topic_id"].startswith("topic-cog")]
    full_db["questions"] = [q for q in full_db["questions"] if not q["topic_id"].startswith("topic-cog")]

    full_db["topics"].extend(c_topics)
    full_db["quick_notes"].extend(c_notes)
    full_db["questions"].extend(c_questions)

    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(full_db, f, ensure_ascii=False, indent=2)

    print(f"\n[BAŞARILI COĞRAFYA HAVUZU] {len(c_topics)} Alt Konu, {len(c_notes)} Hap Bilgi ve {len(c_questions)} Coğrafya Sorusu veritabanına aktarıldı!")
